import React, { useEffect, useState } from 'react';
import { ASSETS } from '../../config/assets';
import { CastShadow } from '../effects/shadows/CastShadow';
import { sfx } from '../../utils/SoundManager';

const HERO_STYLES = `
  @keyframes hologram-entry {
    0% { opacity: 0; transform: perspective(1000px) rotateY(-30deg) translateZ(100px) scale(0.8); filter: blur(10px) brightness(3); }
    100% { opacity: 1; transform: perspective(1000px) rotateY(0deg) translateZ(0) scale(1); filter: blur(0px) brightness(1); }
  }

  .bl-hud-frame {
    position: relative;
    width: 85%;
    height: 80%;
    margin-top: 10%;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    padding: 20px;
    border-left: 2px solid rgba(0, 240, 255, 0.5);
    background: linear-gradient(90deg, rgba(0, 240, 255, 0.05) 0%, transparent 100%);
  }

  .bl-header {
    font-family: 'Teko', sans-serif;
    font-size: 4.5rem;
    font-weight: 800;
    line-height: 0.8;
    color: #fff;
    text-transform: uppercase;
    letter-spacing: -2px;
    -webkit-text-stroke: 1px rgba(0,0,0,0.5);
    margin-bottom: 10px;
  }

  .bl-tag {
    font-family: 'Roboto Mono', monospace;
    font-size: 0.7rem;
    color: #F2D019;
    background: rgba(0,0,0,0.8);
    padding: 2px 8px;
    border: 1px solid #F2D019;
    margin-bottom: 20px;
    letter-spacing: 2px;
  }

  .bl-stats-container {
    display: flex;
    flex-direction: column;
    gap: 8px;
    width: 100%;
  }

  .bl-stat-row {
    display: flex;
    align-items: center;
    gap: 10px;
    width: 100%;
  }

  .bl-stat-label {
    font-family: 'Teko', sans-serif;
    font-size: 1.2rem;
    width: 80px;
    color: rgba(255,255,255,0.7);
  }

  .bl-stat-bar-bg {
    height: 6px;
    flex-grow: 1;
    background: rgba(255,255,255,0.1);
    position: relative;
    overflow: hidden;
  }

  .bl-stat-bar-fill {
    position: absolute;
    top: 0;
    left: 0;
    height: 100%;
    background: #00F0FF;
    box-shadow: 0 0 10px #00F0FF;
  }

  .bl-quote {
    margin-top: 30px;
    font-family: 'Roboto Mono', monospace;
    font-size: 0.8rem;
    color: #fff;
    opacity: 0.8;
    border-left: 3px solid #F2D019;
    padding-left: 10px;
    text-align: left;
  }
`;

const HolographicHUD = ({ onNavigate, activeIndex }: { onNavigate: () => void, activeIndex: number }) => {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    if (activeIndex === 1) {
        setIsVisible(false);
        const timer = setTimeout(() => {
          setIsVisible(true);
          sfx.play('OPEN'); 
        }, 300);
        return () => clearTimeout(timer);
    } else {
        setIsVisible(false);
    }
  }, [activeIndex]);

  if (!isVisible) return null;

  return (
    <>
      <style>{HERO_STYLES}</style>
      <div 
        className="absolute inset-0 flex items-center justify-center pointer-events-auto cursor-pointer z-[200]"
        style={{ animation: 'hologram-entry 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards' }}
        onClick={onNavigate}
      >
        <div className="bl-hud-frame group">
            <div className="bl-tag animate-glitch-active">LEVEL 99 SPECIALIST</div>
            <div className="bl-header group-hover:text-[#F2D019] transition-colors duration-300">
                CREATIVE<br/><span className="text-[#00F0FF]">ARCHITECT</span>
            </div>

            <div className="bl-stats-container mt-4">
                {[
                    { label: "DESIGN", val: "95%" },
                    { label: "CODE", val: "88%" },
                    { label: "AI LOGIC", val: "92%" }
                ].map((s, i) => (
                    <div key={i} className="bl-stat-row">
                        <span className="bl-stat-label">{s.label}</span>
                        <div className="bl-stat-bar-bg">
                            <div className="bl-stat-bar-fill" style={{ width: s.val }} />
                        </div>
                    </div>
                ))}
            </div>

            <div className="bl-quote">
                "Merging visual aesthetics with <br/>neural-driven performance."
            </div>

            {/* HUD Decoration */}
            <div className="absolute top-0 right-0 w-20 h-20 border-t-2 border-r-2 border-[#00F0FF]/30" />
            <div className="absolute bottom-0 left-0 w-full h-[1px] bg-gradient-to-r from-[#00F0FF] to-transparent opacity-50" />
        </div>
      </div>
    </>
  );
};

