            </div>

            {/* Floating Tech Fragments (Decorative) */}
            <div className="absolute -top-10 -right-10 w-16 h-16 animate-float-tech opacity-60">
                 <div className="w-8 h-8 bg-[#F2D019] skew-x-12 rotate-12 shadow-[0_0_15px_#F2D019]" />
            </div>
            <div className="absolute top-1/2 -left-12 w-10 h-10 animate-float-tech opacity-40" style={{ animationDelay: '-2s' }}>
                 <div className="w-4 h-4 bg-[#00F0FF] -rotate-45 shadow-[0_0_10px_#00F0FF]" />
