import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { SVGLoader } from 'three/addons/loaders/SVGLoader.js';
import * as BufferGeometryUtils from 'three/addons/utils/BufferGeometryUtils.js';
import { createMangaMaterial, createOutlineMaterial } from './core/SharedMangaMaterial';

export interface IconConfig {
    boxColor: string;
    shadowColor: string;
    logoColor: string;
    accentColor?: string;
    logoColorRef?: string;
    accentColorRef?: string;
    boxColorRef?: string;

    hatchingDensity?: number;
    hatchingStrength?: number;
    shadowLimit?: number;
    specularLimit?: number;
    outlineWidth?: number;

    isVectorLike?: boolean;
    logoScale?: number;
    depth?: number;
}

interface StandardIcon3DProps {
    svgContent: string;
    config: IconConfig;
}

export const StandardIcon3D: React.FC<StandardIcon3DProps> = ({ svgContent, config }) => {
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!containerRef.current) return;

        // --- CONFIG ---
        const outlineWidth = config.outlineWidth ?? 0.035;
        const lightDir = new THREE.Vector3(0.5, 0.5, 1.2).normalize();

        // --- SCENE SETUP ---
        const width = containerRef.current.clientWidth;
        const height = containerRef.current.clientHeight;
        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 1000);
        // Ajustamos la cámara un poco más cerca ya que no hay caja
        camera.position.set(0, 0, 7);

        const renderer = new THREE.WebGLRenderer({ 
            antialias: true, 
            alpha: true, 
            powerPreference: 'high-performance', 
            precision: 'mediump'
        });
        renderer.setSize(width, height);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        containerRef.current.appendChild(renderer.domElement);

        const floatGroup = new THREE.Group();
        const bounceGroup = new THREE.Group();
        const spinGroup = new THREE.Group();
        const iconMeshGroup = new THREE.Group();
        scene.add(floatGroup); floatGroup.add(bounceGroup); bounceGroup.add(spinGroup); spinGroup.add(iconMeshGroup);

        // --- MATERIALS (Using Shared Engine) ---
        const materialsCache = new Map<string, THREE.ShaderMaterial>();
        const getMat = (color: string) => {
            if (!materialsCache.has(color)) {
                materialsCache.set(color, createMangaMaterial({
                    color,
                    lightDir,
                    hatchingDensity: config.hatchingDensity,
                    hatchingStrength: config.hatchingStrength,
                    shadowLimit: config.shadowLimit,
                    specularLimit: config.specularLimit
                }));
            }
            return materialsCache.get(color)!;
        };

        const outMat = createOutlineMaterial('#000000', outlineWidth);

        // --- SVG LOADING & OPTIMIZATION ---
        const loader = new SVGLoader();
        const svgData = loader.parse(svgContent);
        const logoGroup = new THREE.Group();

        // 1. Calculate Bounds
        let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
        svgData.paths.forEach((path) => {
            const shapes = SVGLoader.createShapes(path);
            shapes.forEach(shape => {
               shape.getPoints().forEach(p => {
                   if(p.x < minX) minX = p.x; if(p.x > maxX) maxX = p.x;
                   if(p.y < minY) minY = p.y; if(p.y > maxY) maxY = p.y;
               });
            });
        });

        const centerX = (minX + maxX) / 2;
        const centerY = (minY + maxY) / 2;
        const scale = config.logoScale || 0.012; 

        // 2. Group Geometries by Color
        const geometriesByColor: Record<string, THREE.BufferGeometry[]> = {};

        svgData.paths.forEach((path) => {
             const shapes = SVGLoader.createShapes(path);
             const fillColor = path.userData.style.fill;

             let useColor = config.logoColor;

             // Ignore background boxes if they match the config 'boxColorRef'
             if (config.boxColorRef && fillColor && fillColor.toLowerCase() === config.boxColorRef.toLowerCase()) return;
             // Specifically ignore Photoshop/Adobe dark blue background boxes if they appear in SVG
             if (fillColor && (fillColor.toLowerCase() === '#001e36' || fillColor.toLowerCase() === '#330000')) return;

             if (config.accentColor && config.accentColorRef && fillColor && fillColor.toLowerCase() === config.accentColorRef.toLowerCase()) {
                 useColor = config.accentColor;
             }

             if (!geometriesByColor[useColor]) {
                 geometriesByColor[useColor] = [];
             }

             shapes.forEach((shape) => {
                 let geometry: THREE.BufferGeometry;
                 const depth = config.depth || 10; // More depth since it stands alone

                 geometry = new THREE.ExtrudeGeometry(shape, { depth, bevelEnabled: true, bevelThickness: 2, bevelSize: 1, bevelSegments: 3 });

                 // Apply transforms
                 geometry.scale(scale, -scale, scale);
                 geometry.translate(-centerX * scale, centerY * scale, 0);

                 geometriesByColor[useColor].push(geometry);
             });
        });

        // 3. Merge and Create Meshes
        Object.keys(geometriesByColor).forEach(colorKey => {
            const geometries = geometriesByColor[colorKey];
            if (geometries.length === 0) return;

            const mergedGeometry = BufferGeometryUtils.mergeGeometries(geometries);
            geometries.forEach(g => g.dispose());

            if (mergedGeometry) {
                mergedGeometry.computeVertexNormals(); 

                const material = getMat(colorKey);
                const mesh = new THREE.Mesh(mergedGeometry, material);

                const outlineMesh = new THREE.Mesh(mergedGeometry, outMat.clone());
                // @ts-ignore
                outlineMesh.material.uniforms.uT.value = outlineWidth * 0.3;
                mesh.add(outlineMesh);

                logoGroup.add(mesh);
            }
        });

        // Center the logo group perfectly
        const bbox = new THREE.Box3().setFromObject(logoGroup);
        const center = new THREE.Vector3();
        bbox.getCenter(center);
        logoGroup.position.sub(center);

        // Aumentar escala un poco ya que no hay caja
        logoGroup.scale.setScalar(1.2);

        iconMeshGroup.add(logoGroup);

        // --- ANIMATION ---
        let time = 0, currentScale = 1, scaleVel = 0, isDragging = false, targetRotX = 0, targetRotY = 0;
        let lastSpinTime = 0, targetSpinY = 0, currentSpinY = 0;
        const raycaster = new THREE.Raycaster(), mouse = new THREE.Vector2(-100, -100);

        const handleMouseMove = (e: MouseEvent) => { if(!containerRef.current)return; const r = containerRef.current.getBoundingClientRect(); mouse.x=((e.clientX-r.left)/r.width)*2-1; mouse.y=-((e.clientY-r.top)/r.height)*2+1; if(isDragging){ targetRotY=mouse.x*0.8; targetRotX=-mouse.y*0.8; } };
        const handleMouseDown = () => { raycaster.setFromCamera(mouse, camera); if(raycaster.intersectObject(logoGroup, true).length>0){ isDragging=true; currentScale=0.85; } };
        const handleMouseUp = () => { isDragging=false; };

        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mousedown', handleMouseDown);
        window.addEventListener('mouseup', handleMouseUp);

        let animationId: number;
        const animate = () => {
            animationId = requestAnimationFrame(animate); time++;

            if (mouse.x > -1.1 && mouse.x < 1.1 && mouse.y > -1.1 && mouse.y < 1.1) {
                raycaster.setFromCamera(mouse, camera);
                if(!isDragging && raycaster.intersectObject(logoGroup, true).length>0 && Date.now()-lastSpinTime>3000){ targetSpinY+=Math.PI*2; lastSpinTime=Date.now(); }
            }

            const spinSpeed = 0.1;
            const springStiffness = 0.12;
            const springDamping = 0.82;

            currentSpinY += (targetSpinY - currentSpinY) * spinSpeed;
            spinGroup.rotation.y = currentSpinY;

            if(isDragging){ iconMeshGroup.rotation.x+=(targetRotX-iconMeshGroup.rotation.x)*0.2; iconMeshGroup.rotation.y+=(targetRotY-iconMeshGroup.rotation.y)*0.2; }
            else { 
                // Idle rotation for floating feel
                iconMeshGroup.rotation.x+=(0-iconMeshGroup.rotation.x)*0.05; 
                iconMeshGroup.rotation.y+=(Math.sin(time * 0.01) * 0.2 - iconMeshGroup.rotation.y)*0.05; 
            }

            scaleVel+=(1-currentScale)*springStiffness; scaleVel*=springDamping; currentScale+=scaleVel;
            bounceGroup.scale.set(currentScale,currentScale,currentScale);
            floatGroup.position.y=Math.sin(time*0.002)*0.1;
            renderer.render(scene, camera);
        };
        animate();

        return () => {
            window.removeEventListener('mousemove', handleMouseMove); 
            window.removeEventListener('mousedown', handleMouseDown); 
            window.removeEventListener('mouseup', handleMouseUp);
            cancelAnimationFrame(animationId); 
            if(containerRef.current && renderer.domElement) containerRef.current.removeChild(renderer.domElement); 
            renderer.dispose();
            materialsCache.forEach(m => m.dispose());
        };
    }, [svgContent, config]);

    return <div ref={containerRef} className="w-full h-full relative" />;
};

