import React, { useState, useEffect } from 'react';
import { sfx } from '../../utils/SoundManager';
import { STACK_DATABASE, WEAPONS_DATABASE } from './data';
import { ViewMode, ItemCategory } from './types';
import { Icons } from './assets/Icons';

// Subcomponents
import { InventoryGrid } from './components/InventoryGrid';
import { InspectorPanel } from './components/InspectorPanel';

interface StackScreenProps {
    onClose: () => void;
}

export const StackScreen: React.FC<StackScreenProps> = ({ onClose }) => {
    const [viewMode, setViewMode] = useState<ViewMode>('RESOURCES');
    const [activeCategory, setActiveCategory] = useState<ItemCategory>('ALL');
    const [selectedItem, setSelectedItem] = useState<any>(STACK_DATABASE[0]);
    const [previewItem, setPreviewItem] = useState<any>(null);
    const [isClosing, setIsClosing] = useState(false);
    const [animateCard, setAnimateCard] = useState(false);

    // Dynamic Theme Colors (Solo para textos y acentos sutiles, ya no para bordes grandes)
    const themeColor = viewMode === 'WEAPONS' ? '#00F0FF' : '#F2D019';
    const themeText = viewMode === 'WEAPONS' ? 'text-[#00F0FF]' : 'text-[#F2D019]';

    useEffect(() => {
        sfx.play('EQUIP');
    }, []);

    const handleClose = () => {
        setIsClosing(true);
        sfx.play('CLICK');
        setTimeout(onClose, 300); 
    };

    const handleSelect = (item: any) => {
        if (item.id === selectedItem.id) return;
        sfx.play('EQUIP');
        setSelectedItem(item);
        setAnimateCard(true);
        setTimeout(() => setAnimateCard(false), 300);
    };

    const handleHover = (item: any | null) => {
        setPreviewItem(item);
        if (item && item.id !== selectedItem.id) sfx.play('HOVER'); 
    };

    const handleModeSwitch = (mode: ViewMode) => {
        if (viewMode === mode) return;
        sfx.play(mode === 'RESOURCES' ? 'CLICK' : 'EQUIP');
        setViewMode(mode);
        setSelectedItem(mode === 'WEAPONS' ? WEAPONS_DATABASE[0] : STACK_DATABASE[0]);
        setPreviewItem(null);
    };

    const itemToDisplay = previewItem || selectedItem;

    return (
        <div className={`
            fixed inset-0 z-[200] flex flex-col items-center
            bg-black overflow-hidden select-none
            ${isClosing ? 'animate-out fade-out duration-300' : 'animate-stack-entry'}
        `}>
            {/* Background Decor - Deep Black Sci-Fi Feel */}
            <div className="absolute inset-0 pointer-events-none z-0" 
                 style={{ 
                     background: `radial-gradient(circle at 50% 30%, #111 0%, #000 80%)`
                 }} 
            />
            {/* Subtle Grid/Dots Overlay */}
            <div className="absolute inset-0 pointer-events-none z-0 opacity-30" 
                 style={{ 
                     backgroundImage: 'radial-gradient(#333 1px, transparent 1px)', 
                     backgroundSize: '30px 30px' 
                 }} 
            />

            {/* HEADER */}
            <div className="relative w-full max-w-[1800px] mt-6 mb-4 z-50 flex flex-col md:flex-row items-center justify-between px-6 gap-4 shrink-0">

                <div className="flex items-stretch h-12 w-full md:w-auto">
                    <button onClick={handleClose} className="relative flex items-center justify-center px-6 md:px-10 h-full bg-[#ef4444] text-black hover:bg-white transition-colors transform -skew-x-[20deg] border-r-4 border-black z-30">
                        <div className="flex items-center gap-2 transform skew-x-[20deg]">
                            <Icons.Close className="w-4 h-4" />
                            <span className="font-['Teko'] text-xl font-bold tracking-widest pt-1">SALIR</span>
                        </div>
                    </button>

                    <button onClick={() => handleModeSwitch('RESOURCES')} 
                        className={`relative flex items-center justify-center px-8 md:px-12 h-full -ml-4 transform -skew-x-[20deg] transition-all border-r-4 border-black ${viewMode === 'RESOURCES' ? 'bg-[#F2D019] text-black z-20' : 'bg-[#18181b] text-gray-500 hover:text-white z-10'}`}>
                        <span className="font-['Teko'] text-xl font-bold tracking-widest pt-1 transform skew-x-[20deg]">SOFTWARE</span>
                    </button>

                    <button onClick={() => handleModeSwitch('WEAPONS')} 
                        className={`relative flex items-center justify-center px-8 md:px-12 h-full -ml-4 transform -skew-x-[20deg] transition-all ${viewMode === 'WEAPONS' ? 'bg-[#00F0FF] text-black z-20' : 'bg-[#18181b] text-gray-500 hover:text-white z-10'}`}>
                        <span className="font-['Teko'] text-xl font-bold tracking-widest pt-1 transform skew-x-[20deg]">ARMAS</span>
                    </button>
                </div>

                <div className="flex flex-col items-end transform -skew-x-[10deg] border-r-4 border-[#333] pr-4 self-end md:self-auto">
                    <h1 className="font-['Teko'] text-4xl font-bold text-white leading-none tracking-wider">STACK PERSONAL</h1>
                    <span className={`font-mono text-[10px] tracking-[0.3em] transition-colors duration-300 ${themeText}`}>
                        {viewMode === 'WEAPONS' ? 'ARMORY MODE ENGAGED' : 'SOFTWARE DATABASE'}
                    </span>
                </div>
            </div>

            {/* MAIN CONTENT AREA */}
            <div className="relative w-full max-w-[1800px] flex-grow flex flex-col lg:flex-row gap-6 p-6 z-10 overflow-hidden h-full pb-8">

                {/* GRID SECTION - Darker, cleaner container */}
                <div className="
                    w-full lg:w-[60%] h-full flex flex-col relative 
                    bg-[#050505] border border-[#222]
                    rounded-tl-2xl rounded-bl-2xl overflow-hidden
                    shadow-[0_0_50px_rgba(0,0,0,0.5)]
                ">
                    <InventoryGrid 
                        viewMode={viewMode} 
                        activeCategory={activeCategory} 
                        onCategoryChange={setActiveCategory} 
                        selectedItem={selectedItem} 
                        onSelect={handleSelect} 
                        onHover={handleHover} 
                    />
                </div>

                {/* INSPECTOR SECTION */}
                <div className="w-full lg:w-[40%] h-full overflow-hidden flex flex-col">
                    <InspectorPanel 
                        selectedItem={itemToDisplay} 
                        animateCard={animateCard} 
                        themeColor={themeColor}
                    />
                </div>
            </div>
        </div>
    );
};

import React, { useMemo } from 'react';
import { StackItem, WeaponConfig, ViewMode, ItemCategory } from '../types';
import { STACK_DATABASE, WEAPONS_DATABASE } from '../data';
