import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { SVGLoader } from 'three/addons/loaders/SVGLoader.js';
import * as BufferGeometryUtils from 'three/addons/utils/BufferGeometryUtils.js';
import { createMangaMaterial, createOutlineMaterial } from './core/SharedMangaMaterial';

export interface IconConfig {
    boxColor: string;
    shadowColor: string;
    logoColor: string;
    accentColor?: string;
    logoColorRef?: string;
    accentColorRef?: string;
    boxColorRef?: string;

    hatchingDensity?: number;
    hatchingStrength?: number;
    shadowLimit?: number;
    specularLimit?: number;
    outlineWidth?: number;

    isVectorLike?: boolean;
    logoScale?: number;
    depth?: number;
}

interface StandardIcon3DProps {
    svgContent: string;
    config: IconConfig;
}

export const StandardIcon3D: React.FC<StandardIcon3DProps> = ({ svgContent, config }) => {
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!containerRef.current) return;

        // --- CONFIG ---
        const outlineWidth = config.outlineWidth ?? 0.035;
        const lightDir = new THREE.Vector3(0.5, 0.5, 1.2).normalize();

        // --- SCENE SETUP ---
        const width = containerRef.current.clientWidth;
        const height = containerRef.current.clientHeight;
        const scene = new THREE.Scene();

        // CAMERA SETUP: Since we removed the box, we might need to be closer or adjust scaling.
        const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 1000);
        camera.position.set(0, 0, 6); // Moved closer (was 7) for floating icon focus

        const renderer = new THREE.WebGLRenderer({ 
            antialias: true, 
            alpha: true, 
            powerPreference: 'high-performance', 
            precision: 'mediump'
        });
        renderer.setSize(width, height);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        containerRef.current.appendChild(renderer.domElement);

        const floatGroup = new THREE.Group();
        const bounceGroup = new THREE.Group();
        const spinGroup = new THREE.Group();
        const iconMeshGroup = new THREE.Group();
        scene.add(floatGroup); floatGroup.add(bounceGroup); bounceGroup.add(spinGroup); spinGroup.add(iconMeshGroup);

        // --- MATERIALS (Using Shared Engine) ---
        const materialsCache = new Map<string, THREE.ShaderMaterial>();
        const getMat = (color: string) => {
            if (!materialsCache.has(color)) {
                materialsCache.set(color, createMangaMaterial({
                    color,
                    lightDir,
                    hatchingDensity: config.hatchingDensity,
                    hatchingStrength: config.hatchingStrength,
                    shadowLimit: config.shadowLimit,
                    specularLimit: config.specularLimit
                }));
            }
            return materialsCache.get(color)!;
        };

        const outMat = createOutlineMaterial('#000000', outlineWidth);

        // --- SVG LOADING & OPTIMIZATION ---
        const loader = new SVGLoader();
        const svgData = loader.parse(svgContent);
        const logoGroup = new THREE.Group();

        // 1. Calculate Bounds
        let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
        svgData.paths.forEach((path) => {
            const shapes = SVGLoader.createShapes(path);
            shapes.forEach(shape => {
               shape.getPoints().forEach(p => {
                   if(p.x < minX) minX = p.x; if(p.x > maxX) maxX = p.x;
                   if(p.y < minY) minY = p.y; if(p.y > maxY) maxY = p.y;
               });
            });
        });

        const centerX = (minX + maxX) / 2;
        const centerY = (minY + maxY) / 2;
        const scale = config.logoScale || 0.012; 

        // 2. Group Geometries by Color
        const geometriesByColor: Record<string, THREE.BufferGeometry[]> = {};

        svgData.paths.forEach((path) => {
             const shapes = SVGLoader.createShapes(path);
             const fillColor = path.userData.style.fill;

             let useColor = config.logoColor;

             // --- FILTERING OUT BACKGROUND BOXES ---
             // We actively skip paths that match the "box color" to prevent 
             // drawing the square container often found in these logos.
             if (config.boxColorRef && fillColor && fillColor.toLowerCase() === config.boxColorRef.toLowerCase()) return;
             if (fillColor && (fillColor.toLowerCase() === '#001e36' || fillColor.toLowerCase() === '#330000')) return;

             if (config.accentColor && config.accentColorRef && fillColor && fillColor.toLowerCase() === config.accentColorRef.toLowerCase()) {
                 useColor = config.accentColor;
             }

             if (!geometriesByColor[useColor]) {
                 geometriesByColor[useColor] = [];
             }

             shapes.forEach((shape) => {
                 let geometry: THREE.BufferGeometry;
                 const depth = config.depth || 15; // Increased depth since it stands alone

                 geometry = new THREE.ExtrudeGeometry(shape, { depth, bevelEnabled: true, bevelThickness: 2, bevelSize: 1, bevelSegments: 3 });

                 // Apply transforms
                 geometry.scale(scale, -scale, scale);
                 geometry.translate(-centerX * scale, centerY * scale, 0);

                 geometriesByColor[useColor].push(geometry);
             });
        });

        // 3. Merge and Create Meshes
        Object.keys(geometriesByColor).forEach(colorKey => {
            const geometries = geometriesByColor[colorKey];
            if (geometries.length === 0) return;

            const mergedGeometry = BufferGeometryUtils.mergeGeometries(geometries);
            geometries.forEach(g => g.dispose());

            if (mergedGeometry) {
                mergedGeometry.computeVertexNormals(); 

                const material = getMat(colorKey);
                const mesh = new THREE.Mesh(mergedGeometry, material);

                const outlineMesh = new THREE.Mesh(mergedGeometry, outMat.clone());
                // @ts-ignore
                outlineMesh.material.uniforms.uT.value = outlineWidth * 0.3;
                mesh.add(outlineMesh);

                logoGroup.add(mesh);
            }
        });

        // Center the logo group perfectly
        const bbox = new THREE.Box3().setFromObject(logoGroup);
        const center = new THREE.Vector3();
        bbox.getCenter(center);
        logoGroup.position.sub(center);

        // Scale Up since box is gone
        logoGroup.scale.setScalar(1.5);

        iconMeshGroup.add(logoGroup);

        // --- ANIMATION ---
        let time = 0, currentScale = 1, scaleVel = 0, isDragging = false, targetRotX = 0, targetRotY = 0;
        let lastSpinTime = 0, targetSpinY = 0, currentSpinY = 0;
        const raycaster = new THREE.Raycaster(), mouse = new THREE.Vector2(-100, -100);

        const handleMouseMove = (e: MouseEvent) => { if(!containerRef.current)return; const r = containerRef.current.getBoundingClientRect(); mouse.x=((e.clientX-r.left)/r.width)*2-1; mouse.y=-((e.clientY-r.top)/r.height)*2+1; if(isDragging){ targetRotY=mouse.x*0.8; targetRotX=-mouse.y*0.8; } };
        const handleMouseDown = () => { raycaster.setFromCamera(mouse, camera); if(raycaster.intersectObject(logoGroup, true).length>0){ isDragging=true; currentScale=0.85; } };
        const handleMouseUp = () => { isDragging=false; };

        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mousedown', handleMouseDown);
        window.addEventListener('mouseup', handleMouseUp);

        let animationId: number;
        const animate = () => {
            animationId = requestAnimationFrame(animate); time++;

            if (mouse.x > -1.1 && mouse.x < 1.1 && mouse.y > -1.1 && mouse.y < 1.1) {
                raycaster.setFromCamera(mouse, camera);
                if(!isDragging && raycaster.intersectObject(logoGroup, true).length>0 && Date.now()-lastSpinTime>3000){ targetSpinY+=Math.PI*2; lastSpinTime=Date.now(); }
            }

            const spinSpeed = 0.1;
            const springStiffness = 0.12;
            const springDamping = 0.82;

            currentSpinY += (targetSpinY - currentSpinY) * spinSpeed;
            spinGroup.rotation.y = currentSpinY;

            if(isDragging){ iconMeshGroup.rotation.x+=(targetRotX-iconMeshGroup.rotation.x)*0.2; iconMeshGroup.rotation.y+=(targetRotY-iconMeshGroup.rotation.y)*0.2; }
            else { 
                // Idle rotation for floating feel
                iconMeshGroup.rotation.x+=(0-iconMeshGroup.rotation.x)*0.05; 
                iconMeshGroup.rotation.y+=(Math.sin(time * 0.01) * 0.2 - iconMeshGroup.rotation.y)*0.05; 
            }

            scaleVel+=(1-currentScale)*springStiffness; scaleVel*=springDamping; currentScale+=scaleVel;
            bounceGroup.scale.set(currentScale,currentScale,currentScale);
            floatGroup.position.y=Math.sin(time*0.002)*0.1;
            renderer.render(scene, camera);
        };
        animate();

        return () => {
            window.removeEventListener('mousemove', handleMouseMove); 
            window.removeEventListener('mousedown', handleMouseDown); 
            window.removeEventListener('mouseup', handleMouseUp);
            cancelAnimationFrame(animationId); 
            if(containerRef.current && renderer.domElement) containerRef.current.removeChild(renderer.domElement); 
            renderer.dispose();
            materialsCache.forEach(m => m.dispose());
        };
    }, [svgContent, config]);

    return <div ref={containerRef} className="w-full h-full relative" />;
};

import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

// --- CONFIGURACIÓN ---
const config = {
    windForce: 0.15, 
    fabricDetail: 0.45,
    shadowOpacity: 0.4,
    edgeScale: 8.8,
    edgeAmp: 0.0328,
    frameSize: 0.0,
    photoInset: 0.013,
    paperColor: new THREE.Color(0x1a1a1a),
    edgeShadowColor: new THREE.Color(0x000000),
    edgeShadowOpacity: 0.5,
    grainAmp: 0.035,
    scratchAmp: 0.011,
    vignette: 0.2,
    seed: 0.0
};

// --- SHADERS ---
const vertexShader = `
uniform float uTime;
uniform float uWindStrength;
uniform float uFabricFreq;

varying vec2 vUv;
varying float vZ;

void main() {
    vUv = uv;
    vec3 pos = position;

    float looseFactor = uv.y; 
    float pinInfluence = pow(looseFactor, 1.5);

    float wave1 = sin(uv.y * 5.0 - uTime * 2.0); 
    float wave2 = sin(uv.x * 8.0 + uTime * 3.0); 

    float ripples = (wave1 * 0.5 + wave2 * 0.2);

    float displacement = (uWindStrength * 2.0 + ripples * uFabricFreq) * pinInfluence;

    pos.x += (sin(displacement) * 0.05) * pinInfluence;
    pos.z += displacement;

    vZ = displacement;

    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
}
`;

const fragmentShader = `
uniform sampler2D uTexture;
uniform float uRatio;

uniform float uEdgeScale;
uniform float uEdgeAmp;
uniform float uFrameSize;
uniform float uPhotoInset;
uniform vec3 uPaperColor;

uniform float uScratchAmp;
uniform float uGrainAmp;
uniform float uVignette;
uniform float uSeed;

uniform vec3 uEdgeShadowColor; 
uniform float uEdgeShadowOpacity; 
uniform float uShadowOpacity;

varying vec2 vUv;
varying float vZ;

vec3 permute(vec3 x) { return mod(((x*34.0)+1.0)*x, 289.0); }

float snoise(vec2 v){
    const vec4 C = vec4(0.211324865405187, 0.366025403784439, -0.577350269189626, 0.024390243902439);
    vec2 i  = floor(v + dot(v, C.yy) );
    vec2 x0 = v - i + dot(i, C.xx);
    vec2 i1;
    i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
    vec4 x12 = x0.xyxy + C.xxzz;
    x12.xy -= i1;
    i = mod(i, 289.0);
    vec3 p = permute( permute( i.y + vec3(0.0, i1.y, 1.0 )) + i.x + vec3(0.0, i1.x, 1.0 ));
    vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), 0.0);
    m = m*m ;
    m = m*m ;
    vec3 x = 2.0 * fract(p * C.www) - 1.0;
    vec3 h = abs(x) - 0.5;
    vec3 ox = floor(x + 0.5);
    vec3 a0 = x - ox;
    m *= 1.79284291400159 - 0.85373472095314 * ( a0*a0 + h*h );
    vec3 g;
    g.x  = a0.x  * x0.x  + h.x  * x0.y;
    g.yz = a0.yz * x12.xz + h.yz * x12.yw;
    return 130.0 * dot(m, g);
}

float fbm(vec2 x) {
    float v = 0.0; float a = 0.5; vec2 shift = vec2(100.0);
    mat2 rot = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.50));
    for (int i = 0; i < 5; ++i) { v += a * snoise(x + uSeed); x = rot * x * 2.0 + shift; a *= 0.5; }
    return v;
}

void main() {
    vec2 uv = vUv - 0.5;
    vec2 aspectUV = uv;
    aspectUV.y /= uRatio;

    float noise = fbm(aspectUV * uEdgeScale); 
    float dist = max(abs(uv.x), abs(uv.y));
    float raggedDist = dist + noise * uEdgeAmp;

    float borderLimit = 0.5 - uFrameSize; 
    float alpha = 1.0 - smoothstep(borderLimit, borderLimit + 0.01, raggedDist);
    if (alpha < 0.01) discard;

    float paperGrain = fbm(vUv * 60.0);
    vec3 paperCol = uPaperColor - paperGrain * 0.05;

    vec4 photoTex = texture2D(uTexture, vUv);

    float photoNoise = snoise(aspectUV * 30.0) * 0.005;
    float photoDist = max(abs(uv.x), abs(uv.y)) + photoNoise;
    float photoLimit = borderLimit - uPhotoInset;
    float photoMask = 1.0 - smoothstep(photoLimit, photoLimit + 0.02, photoDist);

    float scratches = snoise(vec2(vUv.x * 300.0, vUv.y * 3.0));
    float dust = fbm(vUv * 40.0 + uSeed);

    vec3 grungePhoto = photoTex.rgb;
    grungePhoto = mix(grungePhoto, vec3(0.6, 0.5, 0.4), dust * uGrainAmp); 
    grungePhoto -= scratches * uScratchAmp;
    float len = length(uv); 
    grungePhoto -= len * uVignette;

    vec3 finalRGB = mix(paperCol, grungePhoto, photoMask);

    finalRGB += vZ * uShadowOpacity;

    float edgeShadowFactor = smoothstep(borderLimit - 0.05, borderLimit, raggedDist);
    finalRGB = mix(finalRGB, uEdgeShadowColor, edgeShadowFactor * uEdgeShadowOpacity);

    gl_FragColor = vec4(finalRGB, 1.0);
}
`;

const createProceduralFlagTexture = () => {
    const canvas = document.createElement('canvas');
    canvas.width = 600;
    canvas.height = 900; 
    const ctx = canvas.getContext('2d');

    if (ctx) {
        ctx.fillStyle = '#111111';
        ctx.fillRect(0, 0, 600, 900);

        ctx.strokeStyle = '#F2D019';
        ctx.lineWidth = 20;
        ctx.strokeRect(10, 10, 580, 880);

        ctx.strokeStyle = '#222';
        ctx.lineWidth = 2;
        for(let i=0; i<900; i+=40) {
            ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(600, i); ctx.stroke();
        }

        ctx.fillStyle = '#F2D019';
        ctx.fillRect(280, 100, 40, 700);

        ctx.save();
        ctx.translate(300, 450);
        ctx.rotate(-Math.PI / 2); 
        ctx.font = 'bold 90px "Teko", Arial'; 
        ctx.fillStyle = '#FFFFFF';
        ctx.textAlign = 'center';
        ctx.fillText('UNIBELANDS', 0, -100);
        ctx.restore();

        ctx.font = '24px monospace';
        ctx.fillStyle = '#00F0FF'; 
        ctx.textAlign = 'center';
        ctx.fillText('SECTOR 7 // ROOT', 300, 800);

        ctx.fillStyle = '#111';
        ctx.beginPath();
        ctx.arc(300, 200, 80, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#00F0FF';
        ctx.lineWidth = 8;
        ctx.beginPath();
        ctx.arc(300, 200, 70, 0, Math.PI * 2);
        ctx.stroke();

        ctx.fillStyle = '#F2D019';
        ctx.beginPath();
        ctx.moveTo(300, 160);
        ctx.lineTo(340, 230);
        ctx.lineTo(260, 230);
        ctx.closePath();
        ctx.fill();
    }

    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    return { texture, aspect: 600 / 900 };
};

export const Flag: React.FC = () => {
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!containerRef.current) return;

        const width = containerRef.current.clientWidth;
        const height = containerRef.current.clientHeight;

        const scene = new THREE.Scene();
        // Transparent background
        scene.background = null; 

        const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 100);
        // Adjusted camera distance to fill frame better (was 3.5)
        camera.position.set(0, 0, 3.0); 

        const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
        renderer.setSize(width, height);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        containerRef.current.appendChild(renderer.domElement);

        const { texture, aspect } = createProceduralFlagTexture();
        texture.needsUpdate = true;

        const material = new THREE.ShaderMaterial({
            vertexShader: vertexShader,
            fragmentShader: fragmentShader,
            uniforms: {
                uTexture: { value: texture },
                uRatio: { value: aspect },
                uTime: { value: 0 },
                uWindStrength: { value: config.windForce },
                uFabricFreq: { value: config.fabricDetail },
                uShadowOpacity: { value: config.shadowOpacity },
                uEdgeScale: { value: config.edgeScale },
                uEdgeAmp: { value: config.edgeAmp },
                uFrameSize: { value: config.frameSize },
                uPhotoInset: { value: config.photoInset },
                uPaperColor: { value: config.paperColor },
                uScratchAmp: { value: config.scratchAmp },
                uGrainAmp: { value: config.grainAmp },
                uVignette: { value: config.vignette },
                uSeed: { value: config.seed },
                uEdgeShadowColor: { value: config.edgeShadowColor },
                uEdgeShadowOpacity: { value: config.edgeShadowOpacity }
            },
            side: THREE.DoubleSide,
            transparent: true
        });

        const geometry = new THREE.PlaneGeometry(1, 1, 64, 64);
        const mesh = new THREE.Mesh(geometry, material);

        const baseSize = 1.8;
        mesh.scale.set(baseSize * aspect, baseSize, 1);
        scene.add(mesh);

        const clock = new THREE.Clock();
        let animationId: number;

        const animate = () => {
            animationId = requestAnimationFrame(animate);
            const time = clock.getElapsedTime();
            material.uniforms.uTime.value = time;
            let gust = (Math.sin(time * 0.5) + 1.0) * 0.5;
            material.uniforms.uWindStrength.value = gust * config.windForce;
            renderer.render(scene, camera);
        };
        animate();

        const handleResize = () => {
            if (!containerRef.current) return;
            const newW = containerRef.current.clientWidth;
            const newH = containerRef.current.clientHeight;
            camera.aspect = newW / newH;
            camera.updateProjectionMatrix();
            renderer.setSize(newW, newH);
        };
        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationId);
            renderer.dispose();
            geometry.dispose();
            material.dispose();
            texture.dispose();
            if (containerRef.current) {
                containerRef.current.innerHTML = '';
            }
        };
    }, []);

    return <div ref={containerRef} className="w-full h-full pointer-events-none" />;
};

