import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

// --- CONFIGURACIÓN MAPA HOLOGRÁFICO ---
const config = {
    windForce: 0.05, // Menos movimiento para un mapa
    fabricDetail: 0.45,
    shadowOpacity: 0.2,
    edgeScale: 1.0,
    edgeAmp: 0.0,
    frameSize: 0.0,
    photoInset: 0.0,
    paperColor: new THREE.Color(0x002200), // Fondo verde oscuro digital
    edgeShadowColor: new THREE.Color(0x000000),
    edgeShadowOpacity: 0.5,
    grainAmp: 0.035,
    scratchAmp: 0.0,
    vignette: 0.4,
    seed: 0.0
};

// --- SHADERS ---
const vertexShader = `
uniform float uTime;
uniform float uWindStrength;
uniform float uFabricFreq;

varying vec2 vUv;
varying float vZ;

void main() {
    vUv = uv;
    vec3 pos = position;

    // Anclado arriba, suelto abajo (como la bandera original)
    float looseFactor = 1.0 - uv.y; 
    float pinInfluence = pow(looseFactor, 1.5);

    // Movimiento más sutil, tipo distorsión holográfica
    float wave1 = sin(uv.y * 8.0 - uTime * 1.5); 
    float wave2 = sin(uv.x * 12.0 + uTime * 2.0); 

    float ripples = (wave1 * 0.3 + wave2 * 0.1);

    float displacement = (uWindStrength * 1.0 + ripples * uFabricFreq) * pinInfluence;

    pos.x += (sin(displacement) * 0.02) * pinInfluence;
    pos.z += displacement;

    vZ = displacement;

    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
}
`;

const fragmentShader = `
uniform sampler2D uTexture;
uniform float uRatio;
uniform float uTime; // Para efecto scanline

uniform vec3 uPaperColor;
uniform float uVignette;

varying vec2 vUv;
varying float vZ;

void main() {
    vec2 uv = vUv;

    vec4 mapTex = texture2D(uTexture, uv);

    // Color base verde digital
    vec3 hologramColor = mapTex.rgb;

    // Efecto Scanline
    float scanline = sin(uv.y * 800.0 + uTime * 10.0) * 0.05;
    hologramColor += scanline;

    // Brillo pulsante
    float pulse = sin(uTime * 2.0) * 0.1 + 0.9;
    hologramColor *= pulse;

    // Vignette
    vec2 center = uv - 0.5;
    float len = length(center);
    hologramColor *= (1.0 - len * uVignette);

    // Alpha blending based on blackness of texture (additive feel)
    float alpha = mapTex.r + mapTex.g + mapTex.b;
    alpha = smoothstep(0.1, 0.8, alpha) * 0.9; // Transparencia general

    // Borde brillante
    if (uv.x < 0.02 || uv.x > 0.98 || uv.y < 0.02 || uv.y > 0.98) {
        hologramColor = vec3(0.0, 1.0, 0.5);
        alpha = 1.0;
    }

    gl_FragColor = vec4(hologramColor, alpha);
}
`;

const createProceduralMapTexture = () => {
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 512; 
    const ctx = canvas.getContext('2d');

    if (ctx) {
        // Fondo negro
        ctx.fillStyle = '#001100';
        ctx.fillRect(0, 0, 512, 512);

        // Grid
        ctx.strokeStyle = '#004400';
        ctx.lineWidth = 1;
        for(let i=0; i<512; i+=32) {
            ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(512, i); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, 512); ctx.stroke();
        }

        // Topografía abstracta (Círculos concéntricos distorsionados)
        ctx.strokeStyle = '#00FF44';
        ctx.lineWidth = 2;
        for(let r=20; r<200; r+=20) {
            ctx.beginPath();
            for(let a=0; a<=Math.PI*2; a+=0.1) {
                const noise = Math.sin(a*5) * 10 + Math.cos(a*3)*10;
                const x = 256 + Math.cos(a) * (r + noise);
                const y = 256 + Math.sin(a) * (r + noise);
                if (a===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
            ctx.closePath();
            ctx.stroke();
        }

        // Puntos de interés (Loot nodes)
        const nodes = [
            {x: 180, y: 150}, {x: 350, y: 300}, {x: 200, y: 400}, {x: 380, y: 120}
        ];

        nodes.forEach(n => {
            ctx.fillStyle = '#F2D019';
            ctx.beginPath(); ctx.arc(n.x, n.y, 6, 0, Math.PI*2); ctx.fill();
            ctx.strokeStyle = '#F2D019';
            ctx.lineWidth = 1;
            ctx.beginPath(); ctx.arc(n.x, n.y, 12, 0, Math.PI*2); ctx.stroke();
        });

        // X Marks the spot
        ctx.strokeStyle = '#F2D019';
        ctx.lineWidth = 5;
        ctx.beginPath();
        ctx.moveTo(230, 230); ctx.lineTo(282, 282);
        ctx.moveTo(282, 230); ctx.lineTo(230, 282);
        ctx.stroke();

        // Texto Técnico
        ctx.font = '20px monospace';
        ctx.fillStyle = '#00FF44';
        ctx.fillText('SECTOR 7 // LOOT MAP', 20, 480);
        ctx.font = '12px monospace';
        ctx.fillStyle = '#008822';
        ctx.fillText('COORDS: 44.21.99', 20, 500);
    }

    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    return { texture, aspect: 1 };
};

export const Flag: React.FC = () => {
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!containerRef.current) return;

        const width = containerRef.current.clientWidth;
        const height = containerRef.current.clientHeight;

        const scene = new THREE.Scene();
        scene.background = null; 

        const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 100);
        camera.position.set(0, 0, 3.0); 

        const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
        renderer.setSize(width, height);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        containerRef.current.appendChild(renderer.domElement);

        const { texture, aspect } = createProceduralMapTexture();
        texture.needsUpdate = true;

        const material = new THREE.ShaderMaterial({
            vertexShader: vertexShader,
            fragmentShader: fragmentShader,
            uniforms: {
                uTexture: { value: texture },
                uRatio: { value: aspect },
                uTime: { value: 0 },
                uWindStrength: { value: config.windForce },
                uFabricFreq: { value: config.fabricDetail },
                uPaperColor: { value: config.paperColor },
                uVignette: { value: config.vignette }
            },
            side: THREE.DoubleSide,
            transparent: true,
            depthWrite: false, // Mejor para hologramas transparentes
            blending: THREE.AdditiveBlending // Brillo holográfico
        });

        const geometry = new THREE.PlaneGeometry(1, 1, 64, 64);
        const mesh = new THREE.Mesh(geometry, material);

        const baseSize = 2.2; // Un poco más grande para el mapa
        mesh.scale.set(baseSize * aspect, baseSize, 1);
        scene.add(mesh);

        const clock = new THREE.Clock();
        let animationId: number;

        const animate = () => {
            animationId = requestAnimationFrame(animate);
            const time = clock.getElapsedTime();
            material.uniforms.uTime.value = time;
            renderer.render(scene, camera);
        };
        animate();

        const handleResize = () => {
            if (!containerRef.current) return;
            const newW = containerRef.current.clientWidth;
            const newH = containerRef.current.clientHeight;
            camera.aspect = newW / newH;
            camera.updateProjectionMatrix();
            renderer.setSize(newW, newH);
        };
        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationId);
            renderer.dispose();
            geometry.dispose();
            material.dispose();
            texture.dispose();
            if (containerRef.current) {
                containerRef.current.innerHTML = '';
            }
        };
    }, []);

    return <div ref={containerRef} className="w-full h-full pointer-events-none" />;
};

