import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

// --- CONFIGURACIÓN DE TELA ---
const config = {
    windForce: 0.1,
    fabricDetail: 0.8,
    // Colores tipo mapa antiguo / lona
    baseColor: new THREE.Color(0xe3d5c5), 
    inkColor: new THREE.Color(0x3e2b22),
};

// --- SHADERS DE TELA ---
const vertexShader = `
uniform float uTime;
uniform float uWindStrength;

varying vec2 vUv;
varying vec3 vNormal;
varying float vDisplacement;

void main() {
    vUv = uv;
    vec3 pos = position;
    vec3 norm = normal;

    // Anclado a la izquierda (asta de la bandera)
    float looseFactor = uv.x; 

    // Ondulaciones de viento complejas (Simulación de física simple)
    float wave1 = sin(uv.x * 5.0 - uTime * 3.0);
    float wave2 = sin(uv.y * 3.0 + uTime * 2.4);
    float wave3 = sin((uv.x + uv.y) * 2.0 - uTime * 1.5);

    float combinedWave = (wave1 + wave2 * 0.5 + wave3 * 0.3) * looseFactor;

    float displacement = combinedWave * uWindStrength;

    // Desplazar en Z (profundidad)
    pos.z += displacement;

    // Recalcular normales aproximadas para la iluminación
    float delta = 0.05;
    // (Simplificación de normales para efecto low-poly/stylized)
    norm.x -= combinedWave * 0.5; 
    norm = normalize(norm);

    vNormal = norm;
    vDisplacement = displacement;

    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
}
`;

const fragmentShader = `
uniform sampler2D uTexture;
uniform vec3 uBaseColor;

varying vec2 vUv;
varying vec3 vNormal;
varying float vDisplacement;

// Función simple de ruido para la textura de la tela
float rand(vec2 co){
    return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
}

void main() {
    vec4 mapTex = texture2D(uTexture, vUv);

    // 1. Textura Base (Trama de la tela)
    float weave = (sin(vUv.x * 400.0) * sin(vUv.y * 400.0)) * 0.05 + 0.95;
    float noise = rand(vUv) * 0.05;

    // 2. Color del Mapa
    // Si el mapa es oscuro (tinta), usa el color de la textura. Si es claro, usa el color base de la tela.
    float inkFactor = 1.0 - mapTex.g; // Usamos el canal verde invertido como máscara de tinta
    vec3 finalColor = mix(uBaseColor, mapTex.rgb, inkFactor * 0.8);

    // 3. Iluminación Básica (Lambert)
    vec3 lightDir = normalize(vec3(0.5, 0.5, 1.0));
    float diff = max(dot(vNormal, lightDir), 0.0);

    // Sombreado ambiental + direccional
    vec3 lighting = vec3(0.4) + (vec3(0.6) * diff);

    // Sombreado extra en los pliegues profundos
    float foldShadow = 1.0 - (abs(vDisplacement) * 0.5);

    gl_FragColor = vec4(finalColor * weave * lighting * foldShadow, 1.0);
}
`;

const createProceduralMapTexture = () => {
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 512; 
    const ctx = canvas.getContext('2d');

    if (ctx) {
        // Fondo Claro (Papel)
        ctx.fillStyle = '#e3d5c5';
        ctx.fillRect(0, 0, 512, 512);

        // Desgaste / Manchas
        ctx.globalAlpha = 0.1;
        ctx.fillStyle = '#8b7355';
        for(let i=0; i<20; i++) {
            ctx.beginPath();
            ctx.arc(Math.random()*512, Math.random()*512, Math.random()*100, 0, Math.PI*2);
            ctx.fill();
        }
        ctx.globalAlpha = 1.0;

        // Grid Topográfico
        ctx.strokeStyle = '#a69279'; // Marrón muy claro
        ctx.lineWidth = 1;
        for(let i=0; i<512; i+=40) {
            ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(512, i); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, 512); ctx.stroke();
        }

        // Líneas de Tinta (El dibujo del mapa)
        ctx.strokeStyle = '#3e2b22'; // Marrón oscuro tinta
        ctx.lineWidth = 3;
        ctx.lineCap = 'round';

        // Isla central abstracta
        ctx.beginPath();
        ctx.moveTo(150, 150);
        ctx.bezierCurveTo(150, 100, 350, 100, 350, 150);
        ctx.bezierCurveTo(400, 250, 400, 350, 350, 400);
        ctx.bezierCurveTo(250, 450, 150, 450, 150, 400);
        ctx.bezierCurveTo(100, 300, 100, 200, 150, 150);
        ctx.stroke();

        // X Marks the Spot (Rojo desvanecido)
        ctx.strokeStyle = '#8a3324';
        ctx.lineWidth = 8;
        ctx.beginPath();
        ctx.moveTo(230, 250); ctx.lineTo(280, 300);
        ctx.moveTo(280, 250); ctx.lineTo(230, 300);
        ctx.stroke();

        // Texto
        ctx.fillStyle = '#3e2b22';
        ctx.font = 'bold 30px "Courier New", monospace';
        ctx.fillText('SECTOR 7', 180, 450);

        // Brújula simple
        ctx.beginPath(); ctx.arc(450, 60, 30, 0, Math.PI*2); ctx.stroke();
        ctx.font = '20px monospace';
        ctx.fillText('N', 445, 45);
    }

    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.anisotropy = 16;
    return { texture, aspect: 1 };
};

export const Flag: React.FC = () => {
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!containerRef.current) return;

        const width = containerRef.current.clientWidth;
        const height = containerRef.current.clientHeight;

        const scene = new THREE.Scene();

        // Cámara ortográfica para que parezca un objeto plano en el mundo
        const camera = new THREE.PerspectiveCamera(35, width / height, 0.1, 100);
        camera.position.set(0, 0, 4.5); 

        const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
        renderer.setSize(width, height);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        containerRef.current.appendChild(renderer.domElement);

        const { texture } = createProceduralMapTexture();
        texture.needsUpdate = true;

        const material = new THREE.ShaderMaterial({
            vertexShader: vertexShader,
            fragmentShader: fragmentShader,
            uniforms: {
                uTexture: { value: texture },
                uTime: { value: 0 },
                uWindStrength: { value: config.windForce },
                uBaseColor: { value: config.baseColor }
            },
            side: THREE.DoubleSide,
            transparent: false, // TELA OPACA
        });

        // Geometría con suficientes segmentos para que el viento se vea suave
        const geometry = new THREE.PlaneGeometry(1.8, 1.3, 30, 20);

        // Mover el pivote al borde izquierdo para que ondee desde el asta
        geometry.translate(0.9, 0, 0); 

        const mesh = new THREE.Mesh(geometry, material);
        // Rotar ligeramente para perspectiva
        mesh.rotation.y = -0.2; 

        // Centrar visualmente
        mesh.position.x = -0.9;

        scene.add(mesh);

        // Asta de la bandera (simple cilindro oscuro)
        const poleGeo = new THREE.CylinderGeometry(0.02, 0.02, 3, 8);
        const poleMat = new THREE.MeshBasicMaterial({ color: 0x1a1a1a });
        const pole = new THREE.Mesh(poleGeo, poleMat);
        pole.position.x = -0.9;
        pole.position.y = -0.8;
        scene.add(pole);

        const clock = new THREE.Clock();
        let animationId: number;

        const animate = () => {
            animationId = requestAnimationFrame(animate);
            const time = clock.getElapsedTime();
            material.uniforms.uTime.value = time;
            renderer.render(scene, camera);
        };
        animate();

        const handleResize = () => {
            if (!containerRef.current) return;
            const newW = containerRef.current.clientWidth;
            const newH = containerRef.current.clientHeight;
            camera.aspect = newW / newH;
            camera.updateProjectionMatrix();
            renderer.setSize(newW, newH);
        };
        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationId);
            renderer.dispose();
            geometry.dispose();
            material.dispose();
            texture.dispose();
            poleGeo.dispose();
            poleMat.dispose();
            if (containerRef.current) {
                containerRef.current.innerHTML = '';
            }
        };
    }, []);

    return <div ref={containerRef} className="w-full h-full pointer-events-none" />;
};

