import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

// --- CONFIGURACIÓN DE TELA ---
const config = {
    windForce: 0.15, // Un poco más fuerte para que se note hacia arriba
    baseColor: new THREE.Color(0xdbbfa0), // Color más Lona/Arpillera
};

// --- SHADERS DE TELA (UPDRAFT) ---
const vertexShader = `
uniform float uTime;
uniform float uWindStrength;

varying vec2 vUv;
varying vec3 vNormal;
varying float vDisplacement;

void main() {
    vUv = uv;
    vec3 pos = position;

    // Simulación de aire caliente (Updraft)
    // El movimiento es más fuerte en la parte superior (uv.y)
    float looseFactor = uv.y; 

    // Ondas sinusoidales complejas moviéndose en Y (hacia arriba)
    float wave1 = sin(uv.x * 10.0 + uTime * 4.0); // Onda rápida horizontal
    float wave2 = sin(uv.y * 5.0 - uTime * 6.0); // Onda vertical subiendo
    float noise = sin(uv.x * 20.0 + uv.y * 20.0 + uTime * 10.0) * 0.1; // Turbulencia micro

    // Combinar ondas. La bandera "flota" y ondea
    float combinedWave = (wave1 * 0.5 + wave2 + noise) * looseFactor;

    // Desplazamiento principalmente en Z para dar volumen, y un poco en X
    float displacement = combinedWave * uWindStrength;

    pos.z += displacement;
    pos.x += displacement * 0.2; // Ligero movimiento lateral

    // Deformar un poco los bordes para que no sea un plano perfecto
    pos.y += sin(uv.x * 5.0) * 0.05 * looseFactor;

    vec3 norm = normal;
    vNormal = norm;
    vDisplacement = displacement;

    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
}
`;

const fragmentShader = `
uniform sampler2D uTexture;
uniform vec3 uBaseColor;

varying vec2 vUv;
varying vec3 vNormal;
varying float vDisplacement;

// Función de ruido para textura de tela
float rand(vec2 co){
    return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
}

void main() {
    vec4 mapTex = texture2D(uTexture, vUv);

    // 1. Textura de Tela Gruesa (Arpillera/Lona)
    // Alta frecuencia para simular hilos
    float threadX = sin(vUv.x * 800.0);
    float threadY = sin(vUv.y * 800.0);
    float weave = (threadX * threadY) * 0.1 + 0.9;

    // Ruido granulado
    float noise = rand(vUv * 50.0) * 0.1;

    // 2. Color del Mapa
    // Tinta (oscuro) vs Tela (claro)
    float inkFactor = 1.0 - mapTex.g; 

    // Color base más sucio/realista
    vec3 fabricColor = uBaseColor * weave;
    vec3 inkColor = vec3(0.2, 0.15, 0.1); // Marrón muy oscuro

    vec3 finalColor = mix(fabricColor, inkColor, inkFactor * 0.9);

    // 3. Desgaste / Suciedad en los bordes
    float dirt = 1.0 - (pow(abs(vUv.x - 0.5) * 2.0, 4.0) * 0.5);
    finalColor *= dirt;

    // 4. Iluminación
    vec3 lightDir = normalize(vec3(0.2, 0.8, 1.0));
    float diff = max(dot(normalize(vNormal), lightDir), 0.0);

    // Sombreado de pliegues
    float foldShadow = 1.0 - (abs(vDisplacement) * 1.5);

    vec3 lighting = vec3(0.5) + (vec3(0.5) * diff);

    gl_FragColor = vec4(finalColor * lighting * foldShadow, 1.0);

    // Alpha mask para bordes desgastados (opcional, aquí simple)
    if (vUv.y < 0.01 || vUv.y > 0.99) discard;
}
`;

const createProceduralMapTexture = () => {
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 768; // Formato vertical para bandera colgante
    const ctx = canvas.getContext('2d');

    if (ctx) {
        // Fondo
        ctx.fillStyle = '#dbbfa0';
        ctx.fillRect(0, 0, 512, 768);

        // Grid
        ctx.strokeStyle = 'rgba(60, 40, 20, 0.2)';
        ctx.lineWidth = 2;
        for(let i=0; i<768; i+=64) {
            ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(512, i); ctx.stroke();
        }
        for(let i=0; i<512; i+=64) {
            ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, 768); ctx.stroke();
        }

        // Mapa estilizado
        ctx.strokeStyle = '#3e2b22';
        ctx.lineWidth = 5;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        ctx.translate(256, 384);
        ctx.scale(0.8, 0.8);
        ctx.translate(-256, -384);

        // Continente abstracto
        ctx.beginPath();
        ctx.moveTo(150, 200);
        ctx.bezierCurveTo(150, 100, 350, 100, 360, 200);
        ctx.bezierCurveTo(400, 300, 400, 500, 350, 600);
        ctx.bezierCurveTo(250, 650, 150, 600, 140, 500);
        ctx.bezierCurveTo(100, 400, 100, 300, 150, 200);
        ctx.stroke();

        // Rutas
        ctx.setLineDash([15, 10]);
        ctx.lineWidth = 3;
        ctx.strokeStyle = '#8a3324';
        ctx.beginPath();
        ctx.moveTo(200, 300);
        ctx.lineTo(300, 450);
        ctx.stroke();
        ctx.setLineDash([]);

        // Marcadores
        ctx.fillStyle = '#8a3324';
        ctx.beginPath(); ctx.arc(200, 300, 10, 0, Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.arc(300, 450, 15, 0, Math.PI*2); ctx.fill();

        // Texto
        ctx.fillStyle = '#3e2b22';
        ctx.font = 'bold 40px "Courier New"';
        ctx.textAlign = 'center';
        ctx.fillText('SECTOR 07', 256, 150);
        ctx.font = '20px "Courier New"';
        ctx.fillText('CLASSIFIED', 256, 680);
    }

    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.anisotropy = 16;
    return { texture };
};

export const Flag: React.FC = () => {
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!containerRef.current) return;

        const width = containerRef.current.clientWidth;
        const height = containerRef.current.clientHeight;

        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(40, width / height, 0.1, 100);
        camera.position.set(0, 0, 3.5); 

        const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
        renderer.setSize(width, height);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        containerRef.current.appendChild(renderer.domElement);

        const { texture } = createProceduralMapTexture();
        texture.needsUpdate = true;

        const material = new THREE.ShaderMaterial({
            vertexShader: vertexShader,
            fragmentShader: fragmentShader,
            uniforms: {
                uTexture: { value: texture },
                uTime: { value: 0 },
                uWindStrength: { value: config.windForce },
                uBaseColor: { value: config.baseColor }
            },
            side: THREE.DoubleSide,
            transparent: false,
        });

        // Geometría Vertical
        const geometry = new THREE.PlaneGeometry(1.6, 2.2, 25, 35);

        // Centrar geometría

        const mesh = new THREE.Mesh(geometry, material);
        mesh.position.y = 0.2; // Subir un poco
        scene.add(mesh);

        // NO POLE (Palo eliminado a petición)

        const clock = new THREE.Clock();
        let animationId: number;

        const animate = () => {
            animationId = requestAnimationFrame(animate);
            const time = clock.getElapsedTime();
            material.uniforms.uTime.value = time;
            renderer.render(scene, camera);
        };
        animate();

        const handleResize = () => {
            if (!containerRef.current) return;
            const newW = containerRef.current.clientWidth;
            const newH = containerRef.current.clientHeight;
            camera.aspect = newW / newH;
            camera.updateProjectionMatrix();
            renderer.setSize(newW, newH);
        };
        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationId);
            renderer.dispose();
            geometry.dispose();
            material.dispose();
            texture.dispose();
            if (containerRef.current) {
                containerRef.current.innerHTML = '';
            }
        };
    }, []);

    return <div ref={containerRef} className="w-full h-full pointer-events-none" />;
};

