            <div className="absolute inset-0 pointer-events-none z-0 opacity-15" 
                 style={{ 
                     backgroundImage: 'radial-gradient(#555 3px, transparent 3px)', 
                     backgroundSize: '40px 40px' 
                 }} 
            />

            {/* HEADER */}
            <div className="relative w-full max-w-[1800px] mt-6 mb-4 z-50 flex flex-col md:flex-row items-center justify-between px-6 gap-4 shrink-0">

                <div className="flex items-stretch h-14 w-full md:w-auto gap-4">
                    {/* Botón SALIR (Redondeado, sin puntas) */}
                    <button onClick={handleClose} className="relative flex items-center justify-center px-10 h-full bg-[#ef4444] text-black hover:bg-white transition-colors rounded-xl border-2 border-black z-30 shadow-lg">
                        <div className="flex items-center gap-2">
                            <Icons.Close className="w-5 h-5" />
                            <span className="font-['Teko'] text-2xl font-bold tracking-widest pt-1">SALIR</span>
                        </div>
                    </button>

                    {/* Botón SOFTWARE */}
                    <button onClick={() => handleModeSwitch('RESOURCES')} 
                        className={`
                            relative flex items-center justify-center px-12 h-full transform -skew-x-[20deg] transition-all border-2 border-black 
                            ${viewMode === 'RESOURCES' 
                                ? 'bg-[#F2D019] text-black z-20 outline outline-4 outline-white outline-offset-[-4px]' 
                                : 'bg-[#18181b] text-gray-500 hover:text-white z-10'
                            }
                        `}>
                        <span className="font-['Teko'] text-2xl font-bold tracking-widest pt-1 transform skew-x-[20deg]">SOFTWARE</span>
                    </button>

                    {/* Botón ARMAS (AZUL y con OUTLINE blanco grueso si activo) */}
                    <button onClick={() => handleModeSwitch('WEAPONS')} 
                        className={`
                            relative flex items-center justify-center px-12 h-full -ml-4 transform -skew-x-[20deg] transition-all border-2 border-black
                            ${viewMode === 'WEAPONS' 
                                ? 'bg-[#3b82f6] text-white z-20 outline outline-4 outline-white outline-offset-[-4px]' 
                                : 'bg-[#18181b] text-gray-500 hover:text-white z-10'
                            }
                        `}>
                        <span className="font-['Teko'] text-2xl font-bold tracking-widest pt-1 transform skew-x-[20deg]">ARMAS</span>
                    </button>
                </div>

                <div className="flex flex-col items-end transform -skew-x-[10deg] border-r-4 border-white pr-4 self-end md:self-auto">
                    <h1 className="font-['Teko'] text-5xl font-bold text-white leading-none tracking-wider italic">STACK PERSONAL</h1>
                    <span className={`font-mono text-[10px] tracking-[0.3em] font-bold ${themeText}`}>
                        SOFTWARE_DATABASE
                    </span>
                </div>
            </div>

            {/* MAIN CONTENT AREA - UNIFIED CONTAINER (Grid + Inspector, no separate boxes) */}
            <div className="relative w-full max-w-[1800px] flex-grow flex flex-col lg:flex-row gap-12 p-6 z-10 overflow-hidden h-full pb-8">

                {/* GRID SECTION */}
                <div className="w-full lg:w-[65%] h-full flex flex-col relative rounded-xl overflow-hidden bg-black/40 border border-white/10 backdrop-blur-sm">
                    <InventoryGrid 
                        viewMode={viewMode} 
                        activeCategory={activeCategory} 
                        onCategoryChange={setActiveCategory} 
                        selectedItem={selectedItem} 
                        onSelect={handleSelect} 
                        onHover={handleHover} 
                    />
                </div>

                {/* INSPECTOR SECTION - Integrated into Main Background (No box) */}
                <div className="w-full lg:w-[35%] h-full overflow-hidden flex flex-col relative pl-4">
                    <InspectorPanel 
                        selectedItem={itemToDisplay} 
                        animateCard={animateCard} 
                        themeColor={themeColor}
                    />
                </div>
            </div>
        </div>
    );
};

