import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

// --- CONFIGURACIÓN DE TELA ---
const config = {
    windForce: 0.25, // Un poco más fuerte para simular corriente ascendente
    baseColor: new THREE.Color(0xd4c5a9), // Color Lona/Pergamino desgastado
};

// --- SHADERS DE TELA (UPDRAFT - ANCLADO ABAJO) ---
const vertexShader = `
uniform float uTime;
uniform float uWindStrength;

varying vec2 vUv;
varying vec3 vNormal;
varying float vDisplacement;

void main() {
    vUv = uv;
    vec3 pos = position;

    // UPDRAFT SIMULATION (Aire viniendo desde abajo)
    // Queremos que la parte INFERIOR (uv.y cerca de 0) esté quieta/anclada
    // y la parte SUPERIOR (uv.y cerca de 1) se mueva libremente.

    float anchorFactor = pow(uv.y, 1.5); // 0.0 en la base, 1.0 arriba. Exponente para base más rígida.

    // Onda principal subiendo (fase negativa en Y)
    float waveUp = sin(pos.y * 3.5 - uTime * 6.0);

    // Ondas secundarias de turbulencia (flutter)
    float flutter = sin(pos.x * 5.0 + uTime * 10.0) * 0.2;
    float noise = sin(pos.x * 10.0 - pos.y * 8.0 + uTime * 4.0) * 0.1;

    // Combinar desplazamiento
    float displacement = (waveUp + flutter + noise) * uWindStrength * anchorFactor;

    // Aplicar desplazamiento en Z (profundidad)
    pos.z += displacement;

    // Ligero movimiento lateral en X (sway) que aumenta con la altura
    pos.x += sin(uTime * 1.5) * 0.05 * anchorFactor;

    vec3 norm = normal;
    vNormal = norm;
    vDisplacement = displacement;

    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
}
`;

const fragmentShader = `
uniform sampler2D uTexture;
uniform vec3 uBaseColor;

varying vec2 vUv;
varying vec3 vNormal;
varying float vDisplacement;

// Función de ruido
float rand(vec2 co){
    return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
}

void main() {
    vec4 mapTex = texture2D(uTexture, vUv);

    // 1. Textura de Tela (Lona rugosa)
    float thread = sin(vUv.x * 600.0) * sin(vUv.y * 600.0);
    float weave = mix(0.9, 1.0, thread);
    float grain = rand(vUv * 10.0) * 0.1;

    // 2. Mezcla de Color (Tinta vs Tela)
    float inkFactor = 1.0 - mapTex.g; 

    vec3 inkColor = vec3(0.25, 0.15, 0.1); 
    vec3 fabricColor = uBaseColor * (1.0 - grain * 0.5);

    vec3 albedo = mix(fabricColor, inkColor, inkFactor * 0.8);

    // 3. Iluminación
    // Luz desde arriba y enfrente
    vec3 lightDir = normalize(vec3(0.0, 1.0, 1.0));
    // Calcular normales perturbadas por el desplazamiento (aproximación visual)
    vec3 perturbedNormal = normalize(vNormal + vec3(0.0, 0.0, -vDisplacement * 0.5));

    float diff = max(dot(perturbedNormal, lightDir), 0.2);

    // Sombras en los pliegues profundos
    float occlusion = 1.0 - smoothstep(0.0, 0.5, abs(vDisplacement));

    // Iluminación final
    vec3 lighting = vec3(0.6) + (vec3(0.4) * diff);

    gl_FragColor = vec4(albedo * weave * lighting * mix(0.8, 1.0, occlusion), 1.0);
}
`;

const createProceduralMapTexture = () => {
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 768;
    const ctx = canvas.getContext('2d');

    if (ctx) {
        // Fondo base
        ctx.fillStyle = '#d4c5a9';
        ctx.fillRect(0, 0, 512, 768);

        // Manchas de antigüedad
        ctx.globalAlpha = 0.1;
        ctx.fillStyle = '#5c4d3c';
        for(let i=0; i<30; i++) {
            const x = Math.random() * 512;
            const y = Math.random() * 768;
            const r = Math.random() * 100;
            ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI*2); ctx.fill();
        }
        ctx.globalAlpha = 1.0;

        // Grid Cartográfico
        ctx.strokeStyle = 'rgba(80, 60, 40, 0.3)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        for(let x=0; x<=512; x+=64) { ctx.moveTo(x,0); ctx.lineTo(x,768); }
        for(let y=0; y<=768; y+=64) { ctx.moveTo(0,y); ctx.lineTo(512,y); }
        ctx.stroke();

        // Continente (Dibujo Principal)
        ctx.strokeStyle = '#3e2b22';
        ctx.lineWidth = 6;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        ctx.beginPath();
        ctx.moveTo(150, 150);
        ctx.bezierCurveTo(250, 100, 400, 200, 350, 300);
        ctx.bezierCurveTo(300, 400, 450, 500, 300, 600);
        ctx.bezierCurveTo(150, 650, 50, 500, 100, 400);
        ctx.bezierCurveTo(150, 300, 100, 200, 150, 150);
        ctx.stroke();

        // "X" Marks the spot
        ctx.strokeStyle = '#8a3324';
        ctx.lineWidth = 10;
        ctx.beginPath();
        ctx.moveTo(280, 430); ctx.lineTo(320, 470);
        ctx.moveTo(320, 430); ctx.lineTo(280, 470);
        ctx.stroke();

        // Texto SECTOR
        ctx.fillStyle = '#3e2b22';
        ctx.font = 'bold 50px "Courier New"';
        ctx.textAlign = 'center';
        ctx.fillText('SECTOR', 256, 100);
        ctx.font = 'bold 80px "Courier New"';
        ctx.fillText('07', 256, 170);
    }

    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.anisotropy = 16;
    return { texture };
};

export const Flag: React.FC = () => {
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!containerRef.current) return;

        const width = containerRef.current.clientWidth;
        const height = containerRef.current.clientHeight;

        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(40, width / height, 0.1, 100);
        camera.position.set(0, 0, 4.0); 

        const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
        renderer.setSize(width, height);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        containerRef.current.appendChild(renderer.domElement);

        const { texture } = createProceduralMapTexture();
        texture.needsUpdate = true;

        const material = new THREE.ShaderMaterial({
            vertexShader: vertexShader,
            fragmentShader: fragmentShader,
            uniforms: {
                uTexture: { value: texture },
                uTime: { value: 0 },
                uWindStrength: { value: config.windForce },
                uBaseColor: { value: config.baseColor }
            },
            side: THREE.DoubleSide,
            transparent: false,
        });

        // Geometría Plana (Bandera Vertical)
        const geometry = new THREE.PlaneGeometry(1.8, 2.4, 30, 40);
        const mesh = new THREE.Mesh(geometry, material);

        // Ajuste de posición: Dado que la base (0) está quieta, subimos un poco el mesh 
        // para que la base coincida con el punto de origen visual si es necesario.
        mesh.position.y = 0.0; 

        scene.add(mesh);

        const clock = new THREE.Clock();
        let animationId: number;

        const animate = () => {
            animationId = requestAnimationFrame(animate);
            const time = clock.getElapsedTime();
            material.uniforms.uTime.value = time;
            renderer.render(scene, camera);
        };
        animate();

        const handleResize = () => {
            if (!containerRef.current) return;
            const newW = containerRef.current.clientWidth;
            const newH = containerRef.current.clientHeight;
            camera.aspect = newW / newH;
            camera.updateProjectionMatrix();
            renderer.setSize(newW, newH);
        };
        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationId);
            renderer.dispose();
            geometry.dispose();
            material.dispose();
            texture.dispose();
            if (containerRef.current) {
                containerRef.current.innerHTML = '';
            }
        };
    }, []);

    return <div ref={containerRef} className="w-full h-full pointer-events-none" />;
};

