import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

// --- CONFIGURACIÓN DE TELA (DARK MODE) ---
const config = {
    windForce: 0.15,
    baseColor: new THREE.Color(0x1a1a1a), // Color Negro/Carbón
};

// --- SHADERS DE TELA (STANDARD WIND - REVERTIDO) ---
const vertexShader = `
uniform float uTime;
uniform float uWindStrength;

varying vec2 vUv;
varying vec3 vNormal;
varying float vDisplacement;

void main() {
    vUv = uv;
    vec3 pos = position;

    // FÍSICA CLÁSICA: Ondeado lateral (Pinned Left/Top)
    // El movimiento aumenta cuanto más a la derecha (x) y abajo (y) vamos
    float pinFactor = smoothstep(0.0, 1.0, uv.x); 

    // Ondas diagonales compuestas
    float wave1 = sin(pos.x * 2.0 + uTime * 2.5 + pos.y) * 0.5;
    float wave2 = sin(pos.x * 5.0 + uTime * 5.0) * 0.2;
    float noise = sin(uTime * 3.0 + pos.y * 10.0) * 0.05;

    float displacement = (wave1 + wave2 + noise) * uWindStrength * pinFactor;

    // Desplazamiento principal en Z
    pos.z += displacement;

    // Ligero movimiento en Y para dar sensación de peso
    pos.y += sin(uTime + pos.x) * 0.02 * pinFactor;

    vec3 norm = normal;
    vNormal = norm;
    vDisplacement = displacement;

    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
}
`;

const fragmentShader = `
uniform sampler2D uTexture;
uniform vec3 uBaseColor;

varying vec2 vUv;
varying vec3 vNormal;
varying float vDisplacement;

// Función de ruido
float rand(vec2 co){
    return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
}

void main() {
    vec4 mapTex = texture2D(uTexture, vUv);

    // 1. Textura de Tela (Sintética/Táctica)
    float thread = sin(vUv.x * 800.0) * sin(vUv.y * 800.0);
    float weave = mix(0.95, 1.0, thread); // Tejido más fino

    // 2. Mezcla de Color (Negro y Oro)
    // mapTex.r se usa para las líneas doradas
    vec3 goldColor = vec3(0.95, 0.82, 0.1); // #F2D019
    vec3 darkColor = uBaseColor;

    // Si el pixel es claro en la textura, es oro. Si es oscuro, es tela negra.
    float isGold = step(0.5, mapTex.r); 
    vec3 albedo = mix(darkColor, goldColor, mapTex.r * 0.8);

    // 3. Iluminación
    vec3 lightDir = normalize(vec3(0.5, 0.8, 1.0));
    // Normales perturbadas para realismo
    vec3 perturbedNormal = normalize(vNormal + vec3(0.0, 0.0, -vDisplacement * 0.2));

    float diff = max(dot(perturbedNormal, lightDir), 0.0);

    // Brillo especular para el oro
    vec3 viewDir = normalize(vec3(0.0, 0.0, 1.0));
    vec3 reflectDir = reflect(-lightDir, perturbedNormal);
    float spec = pow(max(dot(viewDir, reflectDir), 0.0), 16.0);
    float specular = isGold * spec * 0.8;

    // Sombras suaves
    float occlusion = 1.0 - (abs(vDisplacement) * 0.5);

    vec3 lighting = vec3(0.4) + (vec3(0.6) * diff);

    vec3 finalColor = albedo * weave * lighting * occlusion + (vec3(1.0, 0.9, 0.5) * specular);

    gl_FragColor = vec4(finalColor, 1.0);
}
`;

// GENERADOR DE TEXTURA ESTILO "DARK OPS"
const createProceduralMapTexture = () => {
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 768;
    const ctx = canvas.getContext('2d');

    if (ctx) {
        // Fondo NEGRO
        ctx.fillStyle = '#0a0a0a';
        ctx.fillRect(0, 0, 512, 768);

        // Grid Táctico (Gris oscuro)
        ctx.strokeStyle = '#222222';
        ctx.lineWidth = 2;
        ctx.beginPath();
        for(let x=0; x<=512; x+=64) { ctx.moveTo(x,0); ctx.lineTo(x,768); }
        for(let y=0; y<=768; y+=64) { ctx.moveTo(0,y); ctx.lineTo(512,y); }
        ctx.stroke();

        // Continente (Oro)
        ctx.strokeStyle = '#F2D019';
        ctx.lineWidth = 4;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.shadowColor = '#F2D019';
        ctx.shadowBlur = 10;

        ctx.beginPath();
        ctx.moveTo(150, 150);
        ctx.bezierCurveTo(250, 100, 400, 200, 350, 300);
        ctx.bezierCurveTo(300, 400, 450, 500, 300, 600);
        ctx.bezierCurveTo(150, 650, 50, 500, 100, 400);
        ctx.bezierCurveTo(150, 300, 100, 200, 150, 150);
        ctx.stroke();
        ctx.shadowBlur = 0;

        // "X" Marks the spot (Rojo Táctico)
        ctx.strokeStyle = '#ff0000';
        ctx.lineWidth = 8;
        ctx.beginPath();
        ctx.moveTo(280, 430); ctx.lineTo(320, 470);
        ctx.moveTo(320, 430); ctx.lineTo(280, 470);
        ctx.stroke();

        // Texto SECTOR (Blanco/Plata)
        ctx.fillStyle = '#cccccc';
        ctx.font = 'bold 50px "Teko"';
        ctx.textAlign = 'center';
        ctx.fillText('SECTOR', 256, 100);
        ctx.fillStyle = '#F2D019';
        ctx.font = 'bold 80px "Teko"';
        ctx.fillText('07', 256, 170);

        // Datos UI falsos
        ctx.fillStyle = '#333';
        ctx.fillRect(50, 680, 412, 40);
        ctx.fillStyle = '#00F0FF';
        ctx.fillRect(50, 680, 150, 40);
    }

    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.anisotropy = 16;
    return { texture };
};

export const Flag: React.FC = () => {
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!containerRef.current) return;

        const width = containerRef.current.clientWidth;
        const height = containerRef.current.clientHeight;

        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(40, width / height, 0.1, 100);
        camera.position.set(0, 0, 4.0); 

        const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
        renderer.setSize(width, height);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        containerRef.current.appendChild(renderer.domElement);

        const { texture } = createProceduralMapTexture();
        texture.needsUpdate = true;

        const material = new THREE.ShaderMaterial({
            vertexShader: vertexShader,
            fragmentShader: fragmentShader,
            uniforms: {
                uTexture: { value: texture },
                uTime: { value: 0 },
                uWindStrength: { value: config.windForce },
                uBaseColor: { value: config.baseColor }
            },
            side: THREE.DoubleSide,
            transparent: false,
        });

        const geometry = new THREE.PlaneGeometry(1.8, 2.4, 30, 40);
        const mesh = new THREE.Mesh(geometry, material);
        mesh.position.y = 0.0; 

        scene.add(mesh);

        const clock = new THREE.Clock();
        let animationId: number;

        const animate = () => {
            animationId = requestAnimationFrame(animate);
            const time = clock.getElapsedTime();
            material.uniforms.uTime.value = time;
            renderer.render(scene, camera);
        };
        animate();

        const handleResize = () => {
            if (!containerRef.current) return;
            const newW = containerRef.current.clientWidth;
            const newH = containerRef.current.clientHeight;
            camera.aspect = newW / newH;
            camera.updateProjectionMatrix();
            renderer.setSize(newW, newH);
        };
        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationId);
            renderer.dispose();
            geometry.dispose();
            material.dispose();
            texture.dispose();
            if (containerRef.current) {
                containerRef.current.innerHTML = '';
            }
        };
    }, []);

    return <div ref={containerRef} className="w-full h-full pointer-events-none" />;
};

