import React, { createContext, useContext, useState, useEffect, useRef, useCallback } from 'react';

// --- CONTEXTO DEL EDITOR ---
interface SceneItemData {
    id: string;
    x: number;
    y: number;
    scale: number;
    zIndex: number;
}

interface SceneEditorContextType {
    isEditMode: boolean;
    toggleEditMode: () => void;
    registerItem: (id: string, data: SceneItemData) => void;
    updateItem: (id: string, data: Partial<SceneItemData>) => void;
    items: Record<string, SceneItemData>;
    selectedId: string | null;
    selectItem: (id: string | null) => void;
}

const SceneEditorContext = createContext<SceneEditorContextType>({} as any);

export const useSceneEditor = () => useContext(SceneEditorContext);

export const SceneEditorProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [isEditMode, setIsEditMode] = useState(false); // Por defecto apagado, actívalo con el botón UI
    const [items, setItems] = useState<Record<string, SceneItemData>>({});
    const [selectedId, setSelectedId] = useState<string | null>(null);

    const toggleEditMode = () => {
        setIsEditMode(prev => !prev);
        setSelectedId(null);
    };

    const registerItem = useCallback((id: string, data: SceneItemData) => {
        setItems(prev => ({ ...prev, [id]: { ...data, ...prev[id] } }));
    }, []);

    const updateItem = useCallback((id: string, data: Partial<SceneItemData>) => {
        setItems(prev => ({
            ...prev,
            [id]: { ...prev[id], ...data }
        }));
    }, []);

    const selectItem = (id: string | null) => setSelectedId(id);

    return (
        <SceneEditorContext.Provider value={{ isEditMode, toggleEditMode, registerItem, updateItem, items, selectedId, selectItem }}>
            {children}
            <EditorUI />
        </SceneEditorContext.Provider>
    );
};

// --- COMPONENTE DRAGGABLE WRAPPER ---
interface DraggableObjectProps {
    id: string;
    initialX?: number;
    initialY?: number;
    initialScale?: number;
    initialZ?: number;
    className?: string;
    style?: React.CSSProperties;
    children: React.ReactNode;
}

export const DraggableObject: React.FC<DraggableObjectProps> = ({ 
    id, children, className = '', style = {}, 
    initialX = 0, initialY = 0, initialScale = 1, initialZ = 50 
}) => {
    const { isEditMode, registerItem, updateItem, selectItem, selectedId, items } = useSceneEditor();
    const elementRef = useRef<HTMLDivElement>(null);
    const isDragging = useRef(false);
    const dragStart = useRef({ x: 0, y: 0 });
    const initialPos = useRef({ x: 0, y: 0 });

    // Registrar item al montar
    useEffect(() => {
        registerItem(id, { id, x: initialX, y: initialY, scale: initialScale, zIndex: initialZ });
    }, []);

    const currentItem = items[id] || { x: initialX, y: initialY, scale: initialScale, zIndex: initialZ };
    const isSelected = selectedId === id;

    // Lógica de Teclado (Solo si está seleccionado)
    useEffect(() => {
        if (!isSelected || !isEditMode) return;

        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === '1') {
                // Traer al frente
                updateItem(id, { zIndex: currentItem.zIndex + 10 });
            } else if (e.key === '2') {
                // Enviar atrás
                updateItem(id, { zIndex: currentItem.zIndex - 10 });
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isSelected, isEditMode, id, currentItem.zIndex, updateItem]);

    // Manejadores de Mouse
    const handleMouseDown = (e: React.MouseEvent) => {
        if (!isEditMode) return;
        e.stopPropagation(); // Evitar click en elementos traseros
        e.preventDefault();

        selectItem(id);
        isDragging.current = true;
        dragStart.current = { x: e.clientX, y: e.clientY };
        initialPos.current = { x: currentItem.x, y: currentItem.y };

        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseup', handleMouseUp);
    };

    const handleMouseMove = (e: MouseEvent) => {
        if (!isDragging.current) return;
        const dx = e.clientX - dragStart.current.x;
        const dy = e.clientY - dragStart.current.y; // Invertimos Y porque CSS bottom sube hacia arriba usualmente, pero aquí usaremos transform

        // Para simplificar, usaremos transform translate(x, y) desde el punto de origen
        // Si el usuario quiere moverlo visualmente:
        // dy negativo mueve hacia arriba en pantalla (clientY menor)

        updateItem(id, {
            x: initialPos.current.x + dx,
            y: initialPos.current.y - dy // Invertido para coordinar con sistema cartesiano visual si usamos bottom
        });
    };

    const handleMouseUp = () => {
        isDragging.current = false;
        window.removeEventListener('mousemove', handleMouseMove);
        window.removeEventListener('mouseup', handleMouseUp);
    };

    const handleWheel = (e: React.WheelEvent) => {
        if (!isEditMode || !isSelected) return;
        e.stopPropagation();

        // Rueda abajo (negativo) -> reduce tamaño
        // Rueda arriba (positivo) -> aumenta tamaño
        const delta = e.deltaY > 0 ? -0.05 : 0.05;
        const newScale = Math.max(0.1, currentItem.scale + delta);

        updateItem(id, { scale: parseFloat(newScale.toFixed(2)) });
    };

    // Estilo final
    const finalStyle: React.CSSProperties = {
        ...style,
        position: 'absolute',
        transform: `translate(${currentItem.x}px, ${-currentItem.y}px) scale(${currentItem.scale})`, // -y para que positivo sea arriba visualmente
        zIndex: currentItem.zIndex,
        cursor: isEditMode ? 'move' : 'default',
        outline: (isEditMode && isSelected) ? '2px dashed #F2D019' : 'none',
        transition: isDragging.current ? 'none' : 'transform 0.1s ease-out'
    };

    return (
        <div 
            ref={elementRef}
            className={`${className} ${isEditMode ? 'pointer-events-auto' : ''}`}
            style={finalStyle}
            onMouseDown={handleMouseDown}
            onWheel={handleWheel}
        >
            {/* Etiqueta de Debug */}
            {isEditMode && (
                <div className="absolute top-0 left-0 bg-black/80 text-[#F2D019] text-[9px] font-mono p-1 pointer-events-none whitespace-nowrap z-[9999] -translate-y-full">
                    {id} | Z:{currentItem.zIndex} | S:{currentItem.scale.toFixed(2)}
                </div>
            )}
            {children}
        </div>
    );
};

// --- UI DEL EDITOR (BOTÓN COPIAR) ---
const EditorUI = () => {
    const { isEditMode, toggleEditMode, items } = useSceneEditor();

    const copyConfig = () => {
        const output = Object.entries(items).map(([id, data]) => {
            return `
// ${id}
transform: 'translate(${Math.round(data.x)}px, ${Math.round(-data.y)}px) scale(${data.scale})',
zIndex: ${data.zIndex},
            `.trim();
        }).join('\n\n');

        navigator.clipboard.writeText(output);
        alert("Configuración copiada al portapapeles. ¡Pégala en tu código!");
    };

    return (
        <div className="fixed top-4 left-4 z-[9999] flex flex-col gap-2 font-mono">
            <button 
                onClick={toggleEditMode}
                className={`px-4 py-2 text-xs font-bold border-2 rounded shadow-lg transition-all ${isEditMode ? 'bg-[#F2D019] text-black border-white' : 'bg-black/50 text-gray-400 border-gray-600'}`}
            >
                {isEditMode ? '🟢 EDIT MODE ON' : '⚪ EDIT MODE OFF'}
            </button>

            {isEditMode && (
                <div className="bg-black/90 border border-[#F2D019] p-4 rounded text-white text-xs w-64">
                    <p className="mb-2 text-[#F2D019] font-bold">CONTROLES:</p>
                    <ul className="list-disc pl-4 space-y-1 text-gray-300 mb-4">
                        <li>Clic: Seleccionar/Mover</li>
                        <li>Rueda: Escalar</li>
                        <li>Tecla '1': Traer al frente</li>
                        <li>Tecla '2': Enviar atrás</li>
                    </ul>
                    <button 
                        onClick={copyConfig}
                        className="w-full bg-[#00F0FF] text-black font-bold py-2 hover:bg-white transition-colors"
                    >
                        COPIAR VALORES
                    </button>
                </div>
            )}
        </div>
    );
};

